def bisektion(f, a, b, tol=1e-6):
    if f(a) * f(b) > 0:
        raise ValueError(
            "kein Vorzeichenwechsel")
    while b - a > tol:
        m = (a + b) / 2
        if f(a) * f(m) <= 0:
            b = m
        else:
            a = m
    return (a + b) / 2

bisektion(lambda x: x*x - 2, 1, 2)
